#!/usr/bin/env bash
# Evidence: the commit-scope guard spares HUMANS and refuses AGENTS, in two layers.
#
# GENERATED BY THIS SCRIPT — it writes its own transcript via `exec >"$OUT"`, so
# `generated-by` is a fact about the file rather than a claim about who typed it.
# Re-run to reproduce:
#
#   bash docs/evidence/commit-scope-human-exemption-2026-10-22.sh
#
# The only repositories this creates are throwaway ones in the scratch dir, deleted before exit.
set -uo pipefail

REPO="${REPO:-$HOME/hermes-cortex}"
DEPLOYED="${DEPLOYED:-$HOME/.hermes-cortex/scripts/pre-commit-score}"
HOOKS_PATH="${HOOKS_PATH:-$HOME/.hermes-cortex/hooks}"
OUT="${OUT:-$REPO/docs/evidence/commit-scope-human-exemption-2026-10-22.txt}"
exec >"$OUT" 2>&1

norm() {
  # Strip ANSI colour in BOTH forms: a real ESC byte, and the LITERAL `\033[...m` text a shell
  # script emits when it writes the escape sequence through echo. Terminal decoration is not
  # content, and in a committed transcript it is unreadable noise.
  sed -e "s|$HOME|~|g" \
      -e $'s/\033\\[[0-9;]*m//g' \
      -e 's/\\033\[[0-9;]*m//g'
}
say()  { printf '%s\n' "$*"; }
sayn() { printf '%s\n' "$*" | norm; }
rule() { printf '%s\n' "────────────────────────────────────────────────────────────"; }

say "commit-scope guard: humans spared, agents refused — evidence"
say "captured-at : $(cd "$REPO" && git rev-parse --short HEAD)  (the working tree's revision)"
say "generated-by: docs/evidence/commit-scope-human-exemption-2026-10-22.sh (this file wrote itself)"
rule

say ""
say "1. WHY A HUMAN-VS-AGENT TEST CANNOT BE READ OFF THE ENVIRONMENT"
say "   Humans and agents share ONE unix account here, so every signal the agent can read it can"
say "   also write. Human-capable accounts with a home directory:"
getent passwd | grep -E ':(/home/|/root)' | cut -d: -f1,3,6 | sed 's/^/     /' | norm
say ""
say "   A TTY test is beaten by \`script -qc\`; an env marker can be unset; a name match on the"
say "   command can be routed through a script file. That is WHY the design does not try to"
say "   detect humans: layer 1 sits where only agents appear, and layer 2 reads PARENTAGE."
rule

say ""
say "2. THE PREMISE, MEASURED — process ancestry separates the two cases"
say "   \`ps -o ppid=\` walking this process's parents (portable, so macOS/Titus works too):"
python3 - <<'WALK' 2>&1 | norm | sed 's/^/     /'
import os, subprocess
pid, hops = os.getpid(), 0
while pid and pid not in ("0", "1") and hops < 64:
    comm = subprocess.run(["ps", "-o", "comm=", "-p", str(pid)],
                          capture_output=True, text=True).stdout.strip() or "?"
    print(f"{pid:>8}  {comm}")
    pid = subprocess.run(["ps", "-o", "ppid=", "-p", str(pid)],
                         capture_output=True, text=True).stdout.strip()
    hops += 1
WALK
rule

say ""
say "3. LAYER 2 — the hook's own ancestry decision, BOTH directions, plus its wiring"
say "   \$ bash ops/scripts/pre-commit-score --self-test"
bash "$REPO/ops/scripts/pre-commit-score" --self-test 2>&1 | norm \
  | grep -E "ancestry|runtime|scheduler|setsid|login program|LIVE" | sed 's/^/   /'
bash "$REPO/ops/scripts/pre-commit-score" --self-test >/dev/null 2>&1
say "   self-test rc=$?   (0 = every ancestry branch and its wiring behaves as described)"
say ""
say "   HONEST LIMIT: no LIVE human chain could be captured here — this session has no"
say "   interactive login on the host, and \`ssh localhost\` is refused (Permission denied"
say "   (publickey)), so the sshd-rooted path could not be produced. The human branch is"
say "   therefore proven by the classifier cases above and by the guard's wiring assertion,"
say "   NOT by a live human commit. That escape (an agent adding its own key and committing"
say "   over loopback) is named in section 6."
rule

say ""
say "4. LAYER 2 LIVE — a throwaway repo under the cortex hooks, committed from the AGENT tree"
_live="$(mktemp -d "${TMPDIR:-/tmp}/humanspare.XXXXXX")"
(
  cd "$_live" || exit 1
  git init -q .
  git config user.email probe@example.com
  git config user.name probe
  git config core.hooksPath "$HOOKS_PATH"
  echo one > a.txt
  echo two > b.txt
  git add a.txt b.txt
  sayn "   repo: $_live (NOT hermes-cortex; core.hooksPath = $HOOKS_PATH)"
  say "   → BARE commit from the agent's process tree (must be REFUSED):"
  git commit -m probe 2>&1 | norm | head -4 | sed 's/^/       /'
  say "     rc=${PIPESTATUS[0]}   (1 = refused: the agent path still refuses)"
  say "   → PATHSPEC commit from the same tree (must be ALLOWED):"
  git commit -q -m probe -- a.txt 2>&1 | norm | head -3 | sed 's/^/       /'
  say "     rc=$?   (0 = allowed; the remedy works)"
  say "     committed    : $(git show --pretty=format: --name-only HEAD | tr '\n' ' ')"
  say "     still staged : $(git diff --cached --name-only | tr '\n' ' ')"
)
rm -rf "$_live"
rule

say ""
say "5. LAYER 1 LIVE — the enforcer gate, driven with real fixtures"
python3 - "$REPO" <<'GATE' 2>&1 | norm | sed 's/^/   /'
import importlib.util, sys
from pathlib import Path

repo = Path(sys.argv[1])
spec = importlib.util.spec_from_file_location("enf", repo / "plugins/governance-enforcer/__init__.py")
enf = importlib.util.module_from_spec(spec)
spec.loader.exec_module(enf)

CASES = [
    ("bare commit",                    "git commit -m 'fix'", "block"),
    ("pathspec commit (the remedy)",    "git commit -m 'fix' -- a.sh b.py", "pass"),
    ("--only",                          "git commit --only -m 'fix' a.sh", "pass"),
    ("--no-verify (skips the hook)",    "git commit --no-verify -m 'fix' -- a b", "block"),
    ("-n (git shorthand)",              "git commit -n -m 'fix'", "block"),
    ("compound: bare after &&",         "cd /tmp/x && git commit -m 'fix'", "block"),
    ("heredoc body quoting a commit",   "git commit -q -F - -- a b <<'EOF'\ngit commit -m 'x'\nEOF\n", "pass"),
    ("git push (not this gate)",        "git push origin main", "pass"),
]
bad = 0
for label, command, want in CASES:
    result = enf._check_commit_scope_gate("terminal", {"command": command})
    got = "pass" if result is None else "block"
    mark = "OK  " if got == want else "WRONG"
    if got != want:
        bad += 1
    print(f"{mark} {label:32} want={want:5} got={got}")
print()
print(f"non-terminal tool call (must never reach this gate): "
      f"{enf._check_commit_scope_gate('write_file', {'command': 'git commit -m x'}) is None}")
print(f"rc={bad}   (0 = every fixture behaved; nonzero = cases wrong)")
sys.exit(0 if bad == 0 else 1)
GATE
rule

say ""
say "6. THE CEILING — stated, not hidden"
say "   Same uid means this is prevention-for-the-careless plus attribution-for-the-deliberate."
say "   Escapes that REMAIN after both layers, and why each is still better than silence:"
say "     1. A scripted \`--no-verify\` (inside a .sh) skips the hook entirely. Layer 1 only sees"
say "        commands the agent TYPES, so a bypass hidden in a script reaches neither layer. It is"
say "        already logged: the hook writes a sentinel and post-commit-audit records the miss."
say "     2. ssh-localhost ancestry laundering: a commit over loopback is rooted at sshd and reads"
say "        as human. Needs the agent to add its own key (measured: refused right now, no key)."
say "     3. Editing this hook, or setting the repo's core.hooksPath — same-uid, always available."
say "   Scheduling the commit (cron / at / systemd-run) is NOT on this list any more: the"
say "   classifier fails CLOSED for any ancestry that is neither the runtime nor a login program."
say "   Only privilege separation — a second unix account, where sudo needs a password — makes"
say "   any of these impossible rather than attributable."
rule

say ""
say "7. What this capture covers"
say "   UNCOMMITTED at capture time — the committed copy lands one commit after this run."
say "   HEAD at capture: $(cd "$REPO" && git rev-parse --short HEAD)"
(cd "$REPO" && git status --short -- plugins/governance-enforcer/__init__.py ops/scripts/pre-commit-score tests/test_runtime/test_governance_bypass.py docs/evidence/commit-scope-human-exemption-2026-10-22.sh docs/evidence/commit-scope-human-exemption-2026-10-22.txt | norm | sed 's/^/     /')
rule
say ""
say "end of evidence"
